/// Настройки сборки.
///
/// Всё `const` и с рабочим значением по умолчанию, чтобы обычный
/// `flutter run` запускался. Ответ на вопрос «куда смотрит эта сборка» —
/// чтение одного файла, а не grep по литералам.
abstract final class Env {
  /// Собирать контейнер из моков. Пока это единственный доступный вариант:
  /// приложение локальное, бэкенда у него нет, и `RootFactory` появится
  /// вместе с решением, куда именно отправляется заявка.
  ///
  /// Флаг `const`, поэтому неиспользованная ветка выбрасывается компилятором.
  static const bool useMocks = bool.fromEnvironment(
    'MOCKS',
    defaultValue: true,
  );
}
